export const TABLE_ROOT_SELECTORS = [
  "table",
  "[role='table']",
  "[role='grid']",
  ".el-table",
  ".ant-table",
  ".ant-table-wrapper",
  ".n-data-table",
  ".vxe-table",
  ".ag-root",
  ".ag-theme-alpine",
  ".handsontable",
  ".MuiDataGrid-root",
  ".rc-table"
];

const COMPONENT_TABLE_ROOT_SELECTORS = [
  ".el-table",
  ".ant-table-wrapper",
  ".ant-table",
  ".n-data-table",
  ".vxe-table",
  ".ag-root",
  ".ag-theme-alpine",
  ".handsontable",
  ".MuiDataGrid-root",
  ".rc-table",
  "[role='grid']"
];

const ROW_CELL_SELECTORS = [
  ":scope > th",
  ":scope > td",
  ":scope > .ag-cell",
  ":scope > .n-data-table-td",
  ":scope > .ant-table-cell"
].join(", ");

const BODY_ROW_SELECTORS = [
  ".el-table__body tr.el-table__row",
  ".el-table__fixed-body-wrapper tr.el-table__row",
  ".ant-table-tbody > tr.ant-table-row",
  ".n-data-table-tbody .n-data-table-tr",
  ".vxe-body--row",
  ".ag-center-cols-container .ag-row",
  ".ag-body-viewport .ag-row",
  ".handsontable tbody tr",
  ".MuiDataGrid-row",
  ".rc-table-tbody .rc-table-row",
  "tbody tr",
  "[role='row']"
].join(", ");

const HEADER_CELL_SELECTORS = [
  ".el-table__header th",
  ".el-table__header-wrapper th",
  ".ant-table-thead th",
  ".n-data-table-thead .n-data-table-th",
  "thead th",
  "[role='columnheader']"
].join(", ");

const escapeCsvField = (value: string): string => {
  const normalized = value.replace(/\s+/g, " ").trim();
  if (/[",\n\r]/.test(normalized)) {
    return `"${normalized.replace(/"/g, '""')}"`;
  }

  return normalized;
};

const rowToCsvLine = (cells: string[]): string => cells.map(escapeCsvField).join(",");

const rowsAreSimilar = (left: string[], right: string[]): boolean => {
  if (left.length !== right.length) {
    return false;
  }

  return left.every((cell, index) => cell === right[index]);
};

const getCellText = (cell: Element): string => {
  const title = cell.getAttribute("title")?.trim();
  if (title) {
    return title;
  }

  const labeled = cell.querySelector("[title], [aria-label]");
  const labeledText = labeled?.getAttribute("title")?.trim() || labeled?.getAttribute("aria-label")?.trim();
  if (labeledText) {
    return labeledText;
  }

  const inner = cell.querySelector(".cell, .ag-cell-value, .ant-table-cell, .n-data-table-td");
  const textSource = inner ?? cell;
  return (textSource.textContent ?? "").replace(/\s+/g, " ").trim();
};

const queryRowCells = (row: Element): Element[] => {
  const directCells = Array.from(row.querySelectorAll(ROW_CELL_SELECTORS));
  if (directCells.length) {
    return directCells;
  }

  const nestedCells = Array.from(
    row.querySelectorAll("th, td, .ag-cell, [role='cell'], [role='gridcell'], [role='columnheader']")
  );

  return nestedCells.filter((cell) => {
    const rowAncestor = cell.closest("tr, [role='row'], .ag-row, .MuiDataGrid-row, .n-data-table-tr");
    return rowAncestor === row;
  });
};

const rowHasContent = (row: string[]): boolean => row.some((cell) => cell.length > 0);

const dedupeRowData = (rows: string[][]): string[][] => {
  const seen = new Set<string>();
  const deduped: string[][] = [];

  for (const row of rows) {
    if (!rowHasContent(row)) {
      continue;
    }

    const key = row.join("\u0001");
    if (seen.has(key)) {
      continue;
    }

    seen.add(key);
    deduped.push(row);
  }

  return deduped;
};

const mergeHtmlTableParts = (parts: string[][][]): string[][] => {
  const merged: string[][] = [];

  for (const part of parts) {
    if (!part.length) {
      continue;
    }

    if (!merged.length) {
      merged.push(...part);
      continue;
    }

    const startIndex = part.length > 0 && rowsAreSimilar(merged[0], part[0]) ? 1 : 0;
    merged.push(...part.slice(startIndex));
  }

  return dedupeRowData(merged);
};

const extractFromHtmlTable = (table: HTMLTableElement): string[][] => {
  const rows: string[][] = [];
  const headerRows = table.tHead?.rows;

  if (headerRows?.length) {
    for (const row of Array.from(headerRows)) {
      const cells = queryRowCells(row);
      if (cells.length) {
        rows.push(cells.map(getCellText));
      }
    }
  }

  const bodyRows = table.tBodies.length
    ? Array.from(table.tBodies).flatMap((body) => Array.from(body.rows))
    : Array.from(table.rows);

  for (const row of bodyRows) {
    if (table.tHead?.contains(row)) {
      continue;
    }

    const cells = queryRowCells(row);
    if (cells.length) {
      rows.push(cells.map(getCellText));
    }
  }

  return rows;
};

const extractFromHtmlTablesInRoot = (root: Element): string[][] => {
  const tables = root.matches("table")
    ? [root as HTMLTableElement]
    : Array.from(root.querySelectorAll("table")).filter((table): table is HTMLTableElement => table instanceof HTMLTableElement);

  if (!tables.length) {
    return [];
  }

  return mergeHtmlTableParts(tables.map((table) => extractFromHtmlTable(table)));
};

const extractFromComponentTable = (root: Element): string[][] => {
  const rows: string[][] = [];
  const headerCells = Array.from(root.querySelectorAll(HEADER_CELL_SELECTORS));
  if (headerCells.length) {
    rows.push(headerCells.map(getCellText));
  }

  const bodyRows = Array.from(root.querySelectorAll(BODY_ROW_SELECTORS)).filter(
    (row) => !row.closest("thead, .el-table__header, .ant-table-thead")
  );

  for (const row of bodyRows) {
    const cells = queryRowCells(row);
    if (cells.length) {
      rows.push(cells.map(getCellText));
    }
  }

  return dedupeRowData(rows);
};

const isComponentTableRoot = (root: Element): boolean =>
  COMPONENT_TABLE_ROOT_SELECTORS.some((selector) => root.matches(selector));

const extractTableRows = (root: Element): string[][] => {
  if (isComponentTableRoot(root)) {
    const componentRows = extractFromComponentTable(root);
    if (componentRows.length) {
      return componentRows;
    }
  }

  const htmlRows = extractFromHtmlTablesInRoot(root);
  if (htmlRows.length) {
    return htmlRows;
  }

  return extractFromComponentTable(root);
};

/** Require real table body content, not only empty shells or header-only chrome. */
export const hasExportableTableData = (rows: string[][]): boolean => {
  const filledRows = rows.filter(rowHasContent);
  if (!filledRows.length) {
    return false;
  }

  const dataRows = filledRows.length > 1 ? filledRows.slice(1).filter(rowHasContent) : filledRows;
  if (filledRows.length > 1 && !dataRows.length) {
    return false;
  }

  const targetRows = dataRows.length ? dataRows : filledRows;
  return targetRows.some((row) => row.filter((cell) => cell.length > 0).length >= 2);
};

const isTableVisible = (element: Element): boolean => {
  const rect = element.getBoundingClientRect();
  if (rect.width < 48 || rect.height < 32) {
    return false;
  }

  const style = window.getComputedStyle(element);
  if (style.display === "none" || style.visibility === "hidden" || Number(style.opacity) === 0) {
    return false;
  }

  return true;
};

const dedupeNestedTableRoots = (elements: Element[]): Element[] =>
  elements.filter(
    (element, index, array) => !array.some((other, otherIndex) => otherIndex !== index && other.contains(element))
  );

const preferComponentRoot = (element: Element): Element => {
  const componentRoot = element.closest(COMPONENT_TABLE_ROOT_SELECTORS.join(", "));
  return componentRoot ?? element;
};

/** Scan the document for visible, exportable tables without user interaction. */
export const discoverPageTables = (root: ParentNode = document): Element[] => {
  const candidates: Element[] = [];

  for (const selector of TABLE_ROOT_SELECTORS) {
    for (const element of root.querySelectorAll(selector)) {
      if (!isTableVisible(element)) {
        continue;
      }

      const tableRoot = preferComponentRoot(element);
      if (!candidates.includes(tableRoot)) {
        candidates.push(tableRoot);
      }
    }
  }

  return dedupeNestedTableRoots(candidates).filter((tableRoot) => hasExportableTableData(extractTableRows(tableRoot)));
};

export const pickPrimaryTableRoot = (tables: Element[]): Element | undefined => {
  if (!tables.length) {
    return undefined;
  }

  return [...tables].sort((left, right) => {
    const leftScore = extractTableRows(left).filter(rowHasContent).length;
    const rightScore = extractTableRows(right).filter(rowHasContent).length;
    if (rightScore !== leftScore) {
      return rightScore - leftScore;
    }

    const leftRect = left.getBoundingClientRect();
    const rightRect = right.getBoundingClientRect();
    return rightRect.width * rightRect.height - leftRect.width * leftRect.height;
  })[0];
};

export const findTableRoot = (element: Element): Element | null => {
  const componentRoot = element.closest(COMPONENT_TABLE_ROOT_SELECTORS.join(", "));
  if (componentRoot) {
    return componentRoot;
  }

  let current: Element | null = element;

  while (current && current !== document.documentElement) {
    if (TABLE_ROOT_SELECTORS.some((selector) => current?.matches(selector))) {
      return current;
    }

    current = current.parentElement;
  }

  return null;
};

export const tableRowsToCsv = (rows: string[][]): string | null => {
  if (!hasExportableTableData(rows)) {
    return null;
  }

  const nonEmptyRows = rows.filter(rowHasContent);
  const columnCount = Math.max(...nonEmptyRows.map((row) => row.length));
  const normalizedRows = nonEmptyRows.map((row) => {
    const padded = [...row];
    while (padded.length < columnCount) {
      padded.push("");
    }

    return padded;
  });

  return `${normalizedRows.map(rowToCsvLine).join("\r\n")}\r\n`;
};

export const extractTableCsv = (root: Element): string | null => tableRowsToCsv(extractTableRows(root));

export const downloadTableCsv = (root: Element, fileName?: string): boolean => {
  const csv = extractTableCsv(root);
  if (!csv) {
    return false;
  }

  const blob = new Blob([`\uFEFF${csv}`], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName ?? `table-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.csv`;
  anchor.click();
  URL.revokeObjectURL(url);
  return true;
};
