import type { ContentStartRequest, ElementRect, ElementTarget, FlowStep, RuntimeMessage, StepType } from "../shared/schema";
import { startPostMessageBridge, stopPostMessageBridge } from "./postmessage-bridge";
import { removeTableHint, showTableCsvHint, startPassiveTableDiscovery } from "./table-hint";

const UNSTABLE_ID_PATTERNS = [/^el-id-/, /^rc-tabs-/, /^van-/, /^mui-/, /^:r[0-9a-z]+:/i];

const isStableElementId = (id: string): boolean => {
  if (!id || /\s/.test(id)) {
    return false;
  }

  return !UNSTABLE_ID_PATTERNS.some((pattern) => pattern.test(id));
};

const STABLE_ATTRIBUTE_NAMES = [
  "data-testid",
  "data-test",
  "data-cy",
  "data-qa",
  "aria-label",
  "name",
  "placeholder",
  "title",
  "alt"
];

const cssEscape = (value: string): string => {
  if ("CSS" in window && typeof CSS.escape === "function") {
    return CSS.escape(value);
  }

  return value.replace(/["\\#.:,[\]>+~*^$|=()\s]/g, "\\$&");
};

const quoteAttribute = (value: string): string => value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');

const isUniqueSelector = (selector: string): boolean => {
  try {
    return document.querySelectorAll(selector).length === 1;
  } catch {
    return false;
  }
};

const getElementIndex = (element: Element): number => {
  const siblings = Array.from(element.parentElement?.children ?? []).filter(
    (sibling) => sibling.tagName === element.tagName
  );
  return siblings.indexOf(element) + 1;
};

const getElementText = (element: Element): string => {
  if (element instanceof HTMLInputElement && element.type === "password") {
    return (element.placeholder || "[password]").slice(0, 120);
  }

  const rawText =
    element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement
      ? element.placeholder || element.value
      : element.textContent ?? "";

  return rawText.replace(/\s+/g, " ").trim().slice(0, 120);
};

const getRect = (element: Element): ElementRect => {
  const rect = element.getBoundingClientRect();

  return {
    x: Math.round(rect.x),
    y: Math.round(rect.y),
    width: Math.round(rect.width),
    height: Math.round(rect.height),
    top: Math.round(rect.top),
    right: Math.round(rect.right),
    bottom: Math.round(rect.bottom),
    left: Math.round(rect.left)
  };
};

const collectAttributes = (element: Element): Record<string, string> => {
  const attributes: Record<string, string> = {};

  for (const attribute of Array.from(element.attributes)) {
    if (
      STABLE_ATTRIBUTE_NAMES.includes(attribute.name) ||
      attribute.name === "id" ||
      attribute.name === "class" ||
      attribute.name === "type" ||
      attribute.name.startsWith("data-")
    ) {
      attributes[attribute.name] = attribute.value;
    }
  }

  return attributes;
};

const getXPath = (element: Element): string => {
  if (element.id && isStableElementId(element.id)) {
    return `//*[@id="${quoteAttribute(element.id)}"]`;
  }

  const parts: string[] = [];
  let current: Element | null = element;

  while (current && current.nodeType === Node.ELEMENT_NODE) {
    const tagName = current.tagName.toLowerCase();
    const index = getElementIndex(current);
    parts.unshift(`${tagName}[${index}]`);
    current = current.parentElement;
  }

  return `/${parts.join("/")}`;
};

const buildPathSelector = (element: Element): string => {
  const parts: string[] = [];
  let current: Element | null = element;

  while (current && current !== document.documentElement) {
    const tagName = current.tagName.toLowerCase();
    const index = current.parentElement ? Array.from(current.parentElement.children).indexOf(current) + 1 : 1;
    parts.unshift(`${tagName}:nth-child(${index})`);
    current = current.parentElement;
  }

  return parts.join(" > ");
};

const collectSelectorCandidates = (element: Element): string[] => {
  const candidates: string[] = [];
  const tagName = element.tagName.toLowerCase();
  const id = element.getAttribute("id");

  for (const attributeName of STABLE_ATTRIBUTE_NAMES) {
    const value = element.getAttribute(attributeName);
    if (value) {
      candidates.push(`[${attributeName}="${quoteAttribute(value)}"]`);
      candidates.push(`${tagName}[${attributeName}="${quoteAttribute(value)}"]`);
    }
  }

  if (id && isStableElementId(id)) {
    candidates.push(`#${cssEscape(id)}`);
    candidates.push(`${tagName}#${cssEscape(id)}`);
  }

  const classList = Array.from(element.classList).filter((className) => className.length < 48);
  if (classList.length > 0) {
    candidates.push(`${tagName}.${classList.slice(0, 3).map(cssEscape).join(".")}`);
  }

  candidates.push(buildPathSelector(element));

  return Array.from(new Set(candidates)).filter(Boolean);
};

const inspectElement = (element: Element): ElementTarget => {
  const selectorCandidates = collectSelectorCandidates(element);
  const selector = selectorCandidates.find(isUniqueSelector) ?? selectorCandidates[0] ?? element.tagName.toLowerCase();

  return {
    selector,
    selectorCandidates,
    xpath: getXPath(element),
    tagName: element.tagName,
    text: getElementText(element),
    role: element.getAttribute("role") ?? undefined,
    ariaLabel: element.getAttribute("aria-label") ?? undefined,
    attributes: collectAttributes(element),
    rect: getRect(element)
  };
};

let isRecording = false;
let sessionId = "";
let startedAtMs = 0;
let sequence = 0;
let captureSensitiveValues = false;
let inputTimer: number | undefined;
let selectChangeTimer: number | undefined;
let scrollTimer: number | undefined;

const SELECT_DROPDOWN_SELECTOR =
  ".el-select-dropdown, .el-popper, [role='listbox'], .dropdown-menu, .ant-select-dropdown, .rc-select-dropdown, .n-select-menu";

const isNativeSelectElement = (element: Element): boolean => element instanceof HTMLSelectElement;

const isSelectValueControl = (element: Element): boolean => {
  if (element instanceof HTMLSelectElement) {
    return true;
  }

  if (element instanceof HTMLInputElement) {
    const role = element.getAttribute("role");
    if (role === "combobox" || role === "searchbox") {
      return true;
    }

    return Boolean(element.closest(".el-select, .ant-select, .n-select, .rc-select"));
  }

  return false;
};

const isSelectDropdownInteraction = (element: Element): boolean => Boolean(element.closest(SELECT_DROPDOWN_SELECTOR));

const isSelectChromeClick = (element: Element): boolean => {
  if (isNativeSelectElement(element) || isSelectDropdownInteraction(element)) {
    return true;
  }

  return Boolean(element.closest(".el-select, .ant-select, .n-select, .rc-select, [role='combobox']"));
};

const getEventElement = (target: EventTarget | null): Element | null => {
  if (target instanceof Element) {
    return target;
  }

  if (target instanceof Node) {
    return target.parentElement;
  }

  return null;
};

const getInputValue = (element: Element): string | number | boolean | undefined => {
  if (element instanceof HTMLInputElement) {
    if (element.type === "password") {
      return captureSensitiveValues ? element.value : "[password]";
    }

    if (element.type === "checkbox" || element.type === "radio") {
      return element.checked;
    }

    return element.value;
  }

  if (element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement) {
    return element.value;
  }

  return undefined;
};

const createStep = (type: StepType, element?: Element): FlowStep => ({
  id: `${sessionId}-step-${++sequence}`,
  type,
  timestampMs: Math.max(0, Date.now() - startedAtMs),
  url: window.location.href,
  target: element ? inspectElement(element) : undefined
});

const capturePageHtml = (): string | undefined => {
  try {
    return document.documentElement.outerHTML;
  } catch {
    return undefined;
  }
};

const sendStep = (step: FlowStep): void => {
  const pageHtml = capturePageHtml();
  chrome.runtime
    .sendMessage({ type: "CONTENT_STEP", step, pageHtml } satisfies RuntimeMessage)
    .catch(() => {
      // The background service worker may be unavailable on restricted pages.
    });
};

const recordElementStep = (type: StepType, event: Event): void => {
  if (!isRecording || ("isTrusted" in event && !event.isTrusted)) {
    return;
  }

  const element = getEventElement(event.target);
  if (!element) {
    return;
  }

  const step = createStep(type, element);
  const value = getInputValue(element);

  if (value !== undefined) {
    step.value = value;
  }

  showTableCsvHint(element);
  sendStep(step);
};

const handleClick = (event: MouseEvent): void => {
  const element = getEventElement(event.target);
  if (element && isSelectChromeClick(element)) {
    return;
  }

  recordElementStep("click", event);
};

const handleSubmit = (event: SubmitEvent): void => recordElementStep("submit", event);

const handleChange = (event: Event): void => {
  const element = getEventElement(event.target);
  if (element && isSelectValueControl(element)) {
    window.clearTimeout(inputTimer);
    window.clearTimeout(selectChangeTimer);
    selectChangeTimer = window.setTimeout(() => recordElementStep("change", event), 200);
    return;
  }

  recordElementStep("change", event);
};

const handleInput = (event: Event): void => {
  const element = getEventElement(event.target);
  if (element && isSelectValueControl(element)) {
    return;
  }

  window.clearTimeout(inputTimer);
  inputTimer = window.setTimeout(() => recordElementStep("input", event), 350);
};

const handleKeydown = (event: KeyboardEvent): void => {
  if (!isRecording || !event.isTrusted || !["Enter", "Escape", "Tab"].includes(event.key)) {
    return;
  }

  const element = getEventElement(event.target);
  const step = createStep("keydown", element ?? undefined);
  step.key = event.key;
  sendStep(step);
};

const handleScroll = (): void => {
  if (!isRecording) {
    return;
  }

  window.clearTimeout(scrollTimer);
  scrollTimer = window.setTimeout(() => {
    const step = createStep("scroll");
    step.scroll = {
      x: Math.round(window.scrollX),
      y: Math.round(window.scrollY)
    };
    sendStep(step);
  }, 250);
};

const addListeners = (): void => {
  document.addEventListener("click", handleClick, true);
  document.addEventListener("submit", handleSubmit, true);
  document.addEventListener("change", handleChange, true);
  document.addEventListener("input", handleInput, true);
  document.addEventListener("keydown", handleKeydown, true);
  window.addEventListener("scroll", handleScroll, true);
};

const removeListeners = (): void => {
  document.removeEventListener("click", handleClick, true);
  document.removeEventListener("submit", handleSubmit, true);
  document.removeEventListener("change", handleChange, true);
  document.removeEventListener("input", handleInput, true);
  document.removeEventListener("keydown", handleKeydown, true);
  window.removeEventListener("scroll", handleScroll, true);
  window.clearTimeout(inputTimer);
  window.clearTimeout(selectChangeTimer);
  window.clearTimeout(scrollTimer);
};

const startRecording = (message: ContentStartRequest): void => {
  removeListeners();
  isRecording = true;
  sessionId = message.sessionId;
  startedAtMs = new Date(message.startedAt).getTime();
  captureSensitiveValues = message.captureSensitiveValues;
  sequence = 0;
  addListeners();
  startPassiveTableDiscovery();

  if (message.recordPostMessages) {
    startPostMessageBridge(message.sessionId, message.startedAt);
  }
};

const stopRecording = (): void => {
  isRecording = false;
  captureSensitiveValues = false;
  removeListeners();
  removeTableHint();
  stopPostMessageBridge();
};

chrome.runtime.onMessage.addListener((message: RuntimeMessage) => {
  if (message.type === "CONTENT_START") {
    startRecording(message);
    return;
  }

  if (message.type === "CONTENT_STOP") {
    stopRecording();
  }
});
