import type { FlowStep } from "../shared/schema";

const PM_EVENT = "mv3-recorder-postmessage";

let isListening = false;
let sessionId = "";
let startedAtMs = 0;
let sequence = 0;

const serializeMessageData = (data: unknown): unknown => {
  try {
    return JSON.parse(JSON.stringify(data));
  } catch {
    return String(data);
  }
};

const onPostMessageCaptured = (event: Event): void => {
  const detail = (event as CustomEvent<{ message: unknown; targetOrigin: string }>).detail;
  if (!detail) {
    return;
  }

  const step: FlowStep = {
    id: `${sessionId}-step-${++sequence}`,
    type: "postmessage",
    timestampMs: Math.max(0, Date.now() - startedAtMs),
    url: window.location.href,
    postMessage: {
      data: serializeMessageData(detail.message),
      targetOrigin: detail.targetOrigin
    }
  };

  let pageHtml: string | undefined;
  try {
    pageHtml = document.documentElement.outerHTML;
  } catch {
    pageHtml = undefined;
  }

  chrome.runtime.sendMessage({ type: "CONTENT_STEP", step, pageHtml }).catch(() => {});
};

export const startPostMessageBridge = (session: string, startedAt: string): void => {
  sessionId = session;
  startedAtMs = new Date(startedAt).getTime();
  sequence = 0;

  if (!isListening) {
    document.addEventListener(PM_EVENT, onPostMessageCaptured);
    isListening = true;
  }
};

export const stopPostMessageBridge = (): void => {
  if (isListening) {
    document.removeEventListener(PM_EVENT, onPostMessageCaptured);
    isListening = false;
  }
};
