import {
  discoverPageTables,
  downloadTableCsv,
  extractTableCsv,
  findTableRoot,
  pickPrimaryTableRoot
} from "./table-csv";

const HINT_HOST_ID = "mv3-recorder-table-hint-host";
const HINT_HIDE_MS = 8000;
const PASSIVE_SCAN_DELAYS_MS = [500, 1500, 3000];
const PASSIVE_RESCAN_DEBOUNCE_MS = 900;

let hintHost: HTMLElement | undefined;
let hideTimer: number | undefined;
let lastTableKey = "";
let passiveScanTimers: number[] = [];
let passiveRescanTimer: number | undefined;
let passiveObserver: MutationObserver | undefined;

const getTableKey = (root: Element): string => {
  const id = root.id;
  if (id) {
    return `#${id}`;
  }

  const rect = root.getBoundingClientRect();
  return `${root.tagName}:${Math.round(rect.top)}:${Math.round(rect.left)}:${Math.round(rect.width)}`;
};

const ensureHintHost = (): HTMLElement => {
  if (hintHost?.isConnected) {
    return hintHost;
  }

  hintHost = document.createElement("div");
  hintHost.id = HINT_HOST_ID;
  hintHost.style.cssText = [
    "position: fixed",
    "z-index: 2147483646",
    "pointer-events: auto",
    "font: 12px/1.4 -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
    "color: #0f172a"
  ].join(";");

  document.documentElement.appendChild(hintHost);
  return hintHost;
};

const positionHint = (root: Element): void => {
  const host = ensureHintHost();
  const rect = root.getBoundingClientRect();
  const top = Math.min(Math.max(rect.top + 8, 8), window.innerHeight - 96);
  const left = Math.min(Math.max(rect.left + 8, 8), window.innerWidth - 320);

  host.style.top = `${Math.round(top)}px`;
  host.style.left = `${Math.round(left)}px`;
  host.style.maxWidth = "320px";
};

const buildHintMessage = (tableCount: number, fromInteraction: boolean): string => {
  if (tableCount > 1) {
    return `页面探测到 ${tableCount} 个表格，可将表格数据导出为 CSV。`;
  }

  if (fromInteraction) {
    return "探测到表格元素，可将表格数据导出为 CSV。";
  }

  return "页面中存在表格数据，无需操作即可导出为 CSV。";
};

const buildHintMarkup = (canDownload: boolean, message: string): string => {
  const action = canDownload
    ? `<button type="button" data-mv3-table-download style="margin-left:8px;padding:4px 10px;border:0;border-radius:6px;background:#2563eb;color:#fff;cursor:pointer;font:inherit;">下载 CSV</button>`
    : "";

  return `
    <div data-mv3-table-hint style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:10px;background:#fff;border:1px solid #cbd5e1;box-shadow:0 10px 24px rgba(15,23,42,.18);">
      <span style="flex:1;">${message}</span>
      ${action}
      <button type="button" data-mv3-table-dismiss aria-label="关闭" style="border:0;background:transparent;color:#64748b;cursor:pointer;font-size:16px;line-height:1;padding:0 2px;">×</button>
    </div>
  `;
};

const hideTableHint = (): void => {
  window.clearTimeout(hideTimer);
  hintHost?.replaceChildren();
  lastTableKey = "";
};

export const stopPassiveTableDiscovery = (): void => {
  for (const timer of passiveScanTimers) {
    window.clearTimeout(timer);
  }
  window.clearTimeout(passiveRescanTimer);
  passiveObserver?.disconnect();
  passiveObserver = undefined;
  passiveScanTimers = [];
  passiveRescanTimer = undefined;
};

export const removeTableHint = (): void => {
  stopPassiveTableDiscovery();
  hideTableHint();
  hintHost?.remove();
  hintHost = undefined;
};

const scheduleHide = (): void => {
  window.clearTimeout(hideTimer);
  hideTimer = window.setTimeout(() => hideTableHint(), HINT_HIDE_MS);
};

const renderTableHint = (tableRoot: Element, options: { tableCount: number; fromInteraction: boolean }): void => {
  const tableKey = getTableKey(tableRoot);
  if (tableKey === lastTableKey) {
    scheduleHide();
    return;
  }

  lastTableKey = tableKey;
  const host = ensureHintHost();
  const canDownload = Boolean(extractTableCsv(tableRoot));
  host.innerHTML = buildHintMarkup(canDownload, buildHintMessage(options.tableCount, options.fromInteraction));
  positionHint(tableRoot);

  host.onclick = (event) => {
    const target = event.target;
    if (!(target instanceof HTMLElement)) {
      return;
    }

    if (target.closest("[data-mv3-table-dismiss]")) {
      hideTableHint();
      return;
    }

    if (target.closest("[data-mv3-table-download]")) {
      const downloaded = downloadTableCsv(tableRoot);
      if (!downloaded) {
        window.alert("未能读取到表格数据，请稍候数据加载完成后再试，或先点击表格区域后重新导出。");
        return;
      }

      hideTableHint();
    }
  };

  scheduleHide();
};

const scanPageTables = (): void => {
  const tables = discoverPageTables();
  const primary = pickPrimaryTableRoot(tables);
  if (!primary) {
    return;
  }

  renderTableHint(primary, { tableCount: tables.length, fromInteraction: false });
};

export const startPassiveTableDiscovery = (): void => {
  stopPassiveTableDiscovery();
  scanPageTables();
  passiveScanTimers = PASSIVE_SCAN_DELAYS_MS.map((delayMs) => window.setTimeout(scanPageTables, delayMs));

  passiveObserver = new MutationObserver(() => {
    window.clearTimeout(passiveRescanTimer);
    passiveRescanTimer = window.setTimeout(scanPageTables, PASSIVE_RESCAN_DEBOUNCE_MS);
  });

  if (document.documentElement) {
    passiveObserver.observe(document.documentElement, { childList: true, subtree: true });
  }
};

export const showTableCsvHint = (probedElement: Element): void => {
  const tableRoot = findTableRoot(probedElement);
  if (!tableRoot) {
    return;
  }

  const tables = discoverPageTables();
  const tableCount = tables.includes(tableRoot) ? tables.length : tables.length + 1;
  renderTableHint(tableRoot, { tableCount: Math.max(tableCount, 1), fromInteraction: true });
};
